// Winter Night Aurora — direct 2D canvas painting
const W = 1200, H = 800;
const HORIZON = H * 0.70;

// ---------- seeded noise ----------
let _seed = 1337;
function sr() { _seed = (_seed * 16807) % 2147483647; return (_seed - 1) / 2147483646; }
function hash2(x, y) {
  let h = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return h - Math.floor(h);
}
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const uf = xf * xf * (3 - 2 * xf);
  const vf = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi), b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  return (a * (1 - uf) + b * uf) * (1 - vf) + (c * (1 - uf) + d * uf) * vf;
}
function fbm(x, y, oct) {
  let s = 0, amp = 0.5, f = 1;
  for (let i = 0; i < oct; i++) { s += amp * vnoise(x * f, y * f); f *= 2.03; amp *= 0.5; }
  return s;
}

// ---------- sky base gradient ----------
const sky = ctx.createLinearGradient(0, 0, 0, HORIZON);
sky.addColorStop(0.0, '#04060f');
sky.addColorStop(0.35, '#060c1c');
sky.addColorStop(0.65, '#081426');
sky.addColorStop(0.88, '#0b1c30');
sky.addColorStop(1.0, '#0e2438');
ctx.fillStyle = sky;
ctx.fillRect(0, 0, W, HORIZON + 10);

// ---------- faint airglow and horizon hue ----------
const glow = ctx.createRadialGradient(W * 0.55, HORIZON - 40, 30, W * 0.55, HORIZON - 40, W * 0.85);
glow.addColorStop(0, 'rgba(40,90,90,0.18)');
glow.addColorStop(0.5, 'rgba(25,55,70,0.08)');
glow.addColorStop(1, 'rgba(10,20,35,0)');
ctx.fillStyle = glow;
ctx.fillRect(0, 0, W, HORIZON);

// ---------- stars (jittered, natural brightness) ----------
function drawStars() {
  const N = 260;
  for (let i = 0; i < N; i++) {
    const x = sr() * W;
    const y = sr() * (HORIZON - 60) + 10;
    // brightness power law
    const b = Math.pow(sr(), 2.6);
    const alpha = 0.10 + b * 0.75;
    const r = 0.35 + b * 1.6;
    // slight color variety
    const tint = sr();
    let base = '255,255,255';
    if (tint < 0.15) base = '200,220,255';
    else if (tint > 0.9) base = '255,240,210';
    ctx.fillStyle = 'rgba(' + base + ',' + alpha.toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    // rare halo
    if (b > 0.8) {
      const g = ctx.createRadialGradient(x, y, 0, x, y, r * 6);
      g.addColorStop(0, 'rgba(200,220,255,0.35)');
      g.addColorStop(1, 'rgba(200,220,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(x, y, r * 6, 0, Math.PI * 2); ctx.fill();
    }
  }
}
drawStars();

// ---------- aurora curtain ----------
// boundary functions driven by fbm & sines
function auroraTop(x) {
  const t = x / W;
  return H * 0.055
    + 60 * fbm(x * 0.0045, 3.1, 4)
    + 45 * Math.sin(t * 5.3 + 1.2)
    + 28 * Math.sin(t * 11.7 + 2.6);
}
function auroraBot(x) {
  const t = x / W;
  return H * 0.34
    + 90 * fbm(x * 0.0038, 8.4, 4)
    + 55 * Math.sin(t * 3.1 + 0.6)
    + 22 * Math.sin(t * 9.4 + 3.3);
}
// curtain shaped mask for the teal body
ctx.save();
ctx.beginPath();
ctx.moveTo(0, auroraTop(0));
const steps = 90;
for (let i = 0; i <= steps; i++) { const x = (i / steps) * W; ctx.lineTo(x, auroraTop(x)); }
for (let i = steps; i >= 0; i--) { const x = (i / steps) * W; ctx.lineTo(x, auroraBot(x)); }
ctx.closePath();
ctx.clip();

// base soft band glow inside curtain
const band = ctx.createLinearGradient(0, H * 0.05, 0, H * 0.36);
band.addColorStop(0, 'rgba(80,60,120,0.10)');
band.addColorStop(0.28, 'rgba(60,140,140,0.16)');
band.addColorStop(0.62, 'rgba(80,200,170,0.22)');
band.addColorStop(0.9, 'rgba(60,150,140,0.10)');
band.addColorStop(1, 'rgba(30,80,90,0.02)');
ctx.fillStyle = band;
ctx.fillRect(0, 0, W, H * 0.4);

// many narrow translucent vertical strokes
const STRIPS = 620;
for (let i = 0; i < STRIPS; i++) {
  const x = sr() * W;
  const top = auroraTop(x) + sr() * 20 - 10;
  const bot = auroraBot(x) + sr() * 24 - 12;
  if (bot <= top) continue;
  const w = 0.8 + sr() * 2.6;
  // vertical gradient: violet fringe top, green body, fading foot
  const g = ctx.createLinearGradient(0, top, 0, bot);
  const hueMix = sr();
  const gTop = hueMix < 0.4 ? '120,90,170' : '90,120,150';
  g.addColorStop(0.0, 'rgba(' + gTop + ',0)');
  g.addColorStop(0.12, 'rgba(' + gTop + ',' + (0.06 + sr() * 0.10).toFixed(3) + ')');
  g.addColorStop(0.35, 'rgba(90,200,175,' + (0.06 + sr() * 0.10).toFixed(3) + ')');
  g.addColorStop(0.65, 'rgba(110,225,185,' + (0.08 + sr() * 0.12).toFixed(3) + ')');
  g.addColorStop(0.88, 'rgba(70,160,150,' + (0.05 + sr() * 0.08).toFixed(3) + ')');
  g.addColorStop(1.0, 'rgba(50,110,110,0)');

  const skew = (sr() - 0.5) * 26;
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(x, top);
  ctx.lineTo(x + w, top + skew * 0.2);
  ctx.lineTo(x + w + skew, bot);
  ctx.lineTo(x + skew * 0.6, bot);
  ctx.closePath();
  ctx.fill();
}

// brighter ray filaments
const RAYS = 90;
for (let i = 0; i < RAYS; i++) {
  const x = sr() * W;
  const top = auroraTop(x) + 8 + sr() * 30;
  const bot = auroraBot(x) - sr() * 40;
  if (bot <= top) continue;
  const w = 0.6 + sr() * 1.4;
  const g = ctx.createLinearGradient(0, top, 0, bot);
  const a = 0.10 + sr() * 0.14;
  g.addColorStop(0, 'rgba(150,130,190,0)');
  g.addColorStop(0.2, 'rgba(140,170,200,' + (a * 0.6).toFixed(3) + ')');
  g.addColorStop(0.55, 'rgba(170,240,200,' + a.toFixed(3) + ')');
  g.addColorStop(0.9, 'rgba(80,170,160,0)');
  ctx.fillStyle = g;
  ctx.fillRect(x, top, w, bot - top);
}
ctx.restore();

// faint violet upper fringe (outside band, soft)
ctx.save();
ctx.globalCompositeOperation = 'screen';
for (let i = 0; i < 60; i++) {
  const x = sr() * W;
  const top = auroraTop(x) - 40 + sr() * 20;
  const h = 30 + sr() * 60;
  const g = ctx.createLinearGradient(0, top, 0, top + h);
  g.addColorStop(0, 'rgba(120,90,170,0)');
  g.addColorStop(0.5, 'rgba(130,100,180,' + (0.04 + sr() * 0.05).toFixed(3) + ')');
  g.addColorStop(1, 'rgba(130,100,180,0)');
  ctx.fillStyle = g;
  ctx.fillRect(x, top, 1 + sr() * 3, h);
}
ctx.restore();

// ---------- distant atmospheric haze near horizon ----------
const haze = ctx.createLinearGradient(0, HORIZON - 70, 0, HORIZON + 30);
haze.addColorStop(0, 'rgba(20,45,60,0)');
haze.addColorStop(0.7, 'rgba(22,50,65,0.28)');
haze.addColorStop(1, 'rgba(28,60,75,0.5)');
ctx.fillStyle = haze;
ctx.fillRect(0, HORIZON - 70, W, 100);

// ---------- jagged mountains ----------
function ridge(baseY, amp, freq, color, seedOff) {
  ctx.beginPath();
  ctx.moveTo(0, H);
  const n = 200;
  for (let i = 0; i <= n; i++) {
    const x = (i / n) * W;
    const t = x / W;
    const jag = fbm(x * freq + seedOff, seedOff * 2.3, 5);
    const y = baseY - jag * amp - Math.abs(Math.sin(t * Math.PI * 3 + seedOff)) * amp * 0.3;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}
// far range
ridge(HORIZON - 5, 70, 0.006, '#0a1526', 1.3);
// mid range
ridge(HORIZON + 20, 95, 0.008, '#0a1828', 4.7);
// nearer ridge
ridge(HORIZON + 55, 80, 0.011, '#0c1c2c', 9.1);

// moonlit rim light on nearest ridge
ctx.save();
ctx.globalCompositeOperation = 'lighter';
ctx.beginPath();
const rn = 200;
for (let i = 0; i <= rn; i++) {
  const x = (i / rn) * W;
  const jag = fbm(x * 0.011 + 9.1, 18.2, 5);
  const y = HORIZON + 55 - jag * 80 - Math.abs(Math.sin((x / W) * Math.PI * 3 + 9.1)) * 24;
  if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
}
ctx.strokeStyle = 'rgba(120,170,190,0.18)';
ctx.lineWidth = 1.4;
ctx.stroke();
ctx.restore();

// ---------- snowy foreground ----------
const snowTop = HORIZON + 95;
// base snow color
const snowGrad = ctx.createLinearGradient(0, snowTop, 0, H);
snowGrad.addColorStop(0, '#7d8ea0');
snowGrad.addColorStop(0.4, '#94a4b6');
snowGrad.addColorStop(1, '#b3c0ce');
ctx.fillStyle = snowGrad;
ctx.beginPath();
ctx.moveTo(0, H);
ctx.lineTo(0, snowTop + 30);
const sn = 120;
const snowYs = [];
for (let i = 0; i <= sn; i++) {
  const x = (i / sn) * W;
  const t = x / W;
  const y = snowTop
    + 40 * fbm(x * 0.005, 0.5, 4)
    + 18 * Math.sin(t * 6.2 + 0.8)
    + 10 * Math.sin(t * 15.3 + 2.1)
    - 20;
  snowYs.push({ x, y });
  ctx.lineTo(x, y);
}
ctx.lineTo(W, H);
ctx.closePath();
ctx.fill();

// distant snow blending at base of mountains
const snowBaseFade = ctx.createLinearGradient(0, snowTop - 20, 0, snowTop + 80);
snowBaseFade.addColorStop(0, 'rgba(20,35,55,0.55)');
snowBaseFade.addColorStop(1, 'rgba(20,35,55,0)');
ctx.fillStyle = snowBaseFade;
ctx.fillRect(0, snowTop - 20, W, 100);

// gentle teal light from aurora reflecting on snow near horizon
ctx.save();
ctx.globalCompositeOperation = 'screen';
const tealRefl = ctx.createLinearGradient(0, snowTop, 0, snowTop + 130);
tealRefl.addColorStop(0, 'rgba(90,190,170,0.14)');
tealRefl.addColorStop(0.6, 'rgba(70,150,140,0.05)');
tealRefl.addColorStop(1, 'rgba(60,120,120,0)');
ctx.fillStyle = tealRefl;
ctx.fillRect(0, snowTop, W, 130);
ctx.restore();

// undulating blue-gray shadow bands on snow
ctx.save();
for (let i = 0; i < 22; i++) {
  const yBase = snowTop + 20 + sr() * (H - snowTop - 40);
  const depth = (yBase - snowTop) / (H - snowTop);
  const alpha = 0.06 + depth * 0.12;
  ctx.beginPath();
  const startX = -60;
  ctx.moveTo(startX, yBase);
  const segs = 24;
  for (let k = 0; k <= segs; k++) {
    const x = startX + (W + 120) * (k / segs);
    const yy = yBase + Math.sin(x * 0.011 + i * 1.7) * (6 + depth * 16)
      + fbm(x * 0.004 + i * 2.1, i * 1.3, 3) * 18;
    ctx.lineTo(x, yy);
  }
  ctx.lineTo(W + 60, yBase + 40 + 30 * sr());
  ctx.lineTo(-60, yBase + 40 + 30 * sr());
  ctx.closePath();
  const g = ctx.createLinearGradient(0, yBase - 20, 0, yBase + 45);
  g.addColorStop(0, 'rgba(90,115,150,0)');
  g.addColorStop(0.5, 'rgba(70,95,135,' + alpha.toFixed(3) + ')');
  g.addColorStop(1, 'rgba(70,95,135,0)');
  ctx.fillStyle = g;
  ctx.fill();
}
ctx.restore();

// fine snow texture strokes / sparkle highlights
for (let i = 0; i < 2600; i++) {
  const x = sr() * W;
  const y = snowTop + sr() * (H - snowTop);
  const depth = (y - snowTop) / (H - snowTop);
  if (sr() < 0.5) {
    // shadow specks
    ctx.fillStyle = 'rgba(70,95,130,' + (0.05 + depth * 0.08).toFixed(3) + ')';
  } else {
    // highlight sparkles near bottom
    ctx.fillStyle = 'rgba(220,235,245,' + (0.04 + depth * 0.10).toFixed(3) + ')';
  }
  const r = 0.6 + sr() * (0.8 + depth * 1.2);
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

// snow drifts: soft crescent highlights
for (let i = 0; i < 40; i++) {
  const x = sr() * W;
  const y = snowTop + 20 + sr() * (H - snowTop - 30);
  const rw = 20 + sr() * 90;
  const rh = 4 + sr() * 12;
  const g = ctx.createRadialGradient(x, y, 0, x, y, rw);
  g.addColorStop(0, 'rgba(200,215,228,0.10)');
  g.addColorStop(1, 'rgba(200,215,228,0)');
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, rh / rw);
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, rw, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

// ---------- evergreen cluster lower-left ----------
function pineTree(cx, baseY, h, width, dark) {
  const layers = 6 + Math.floor(sr() * 3);
  for (let l = 0; l < layers; l++) {
    const t = l / layers;
    const y = baseY - h * t;
    const w = width * (1 - t * 0.8) * (0.7 + sr() * 0.5);
    const sway = (sr() - 0.5) * 5;
    // layered triangular boughs with jagged edges
    ctx.beginPath();
    ctx.moveTo(cx + sway, y - h * 0.14);
    const kL = 6;
    for (let k = 1; k <= kL; k++) {
      const px = cx - w * (k / kL) + (sr() - 0.5) * w * 0.12;
      const py = y + (h / layers) * 0.15 * (k / kL);
      ctx.lineTo(px, py);
    }
    // tip
    ctx.lineTo(cx + sway, y + h / layers * 0.9);
    for (let k = kL; k >= 1; k--) {
      const px = cx + w * (k / kL) + (sr() - 0.5) * w * 0.12;
      const py = y + (h / layers) * 0.15 * (k / kL);
      ctx.lineTo(px, py);
    }
    ctx.closePath();
    const shade = dark + t * 10;
    ctx.fillStyle = 'rgb(' + (6 + shade) + ',' + (12 + shade) + ',' + (20 + shade * 1.3) + ')';
    ctx.fill();
  }
  // trunk
  ctx.fillStyle = 'rgb(8,10,16)';
  ctx.fillRect(cx - 1.2, baseY - h * 0.12, 2.4, h * 0.14);
}

// cluster positions (lower-left)
const cluster = [
  { x: 70, y: H - 15, h: 210, w: 46 },
  { x: 120, y: H - 10, h: 250, w: 52 },
  { x: 165, y: H - 20, h: 175, w: 40 },
  { x: 55, y: H - 30, h: 140, w: 32 },
  { x: 200, y: H - 5, h: 130, w: 30 },
  { x: 38, y: H - 40, h: 95, w: 22 }
];
for (const t of cluster) {
  pineTree(t.x, t.y, t.h, t.w, 4);
}

// soft ground shadow under cluster
const sh = ctx.createRadialGradient(120, H - 10, 10, 120, H - 10, 200);
sh.addColorStop(0, 'rgba(30,45,65,0.35)');
sh.addColorStop(1, 'rgba(30,45,65,0)');
ctx.fillStyle = sh;
ctx.beginPath();
ctx.ellipse(120, H - 10, 200, 50, 0, 0, Math.PI * 2);
ctx.fill();

// ---------- subtle stars near horizon reflection / faint haze veil ----------
ctx.save();
ctx.globalCompositeOperation = 'screen';
const veil = ctx.createLinearGradient(0, HORIZON - 40, 0, HORIZON + 60);
veil.addColorStop(0, 'rgba(60,120,120,0)');
veil.addColorStop(0.5, 'rgba(60,120,120,0.05)');
veil.addColorStop(1, 'rgba(60,120,120,0)');
ctx.fillStyle = veil;
ctx.fillRect(0, HORIZON - 40, W, 100);
ctx.restore();

// very faint overall cool vignette for cohesion
const vig = ctx.createRadialGradient(W * 0.5, H * 0.42, H * 0.3, W * 0.5, H * 0.42, W * 0.85);
vig.addColorStop(0, 'rgba(0,0,0,0)');
vig.addColorStop(1, 'rgba(0,0,10,0.32)');
ctx.fillStyle = vig;
ctx.fillRect(0, 0, W, H);
